    readonly dualFboGetAWriteTex: 'dual_fbo_get_a_write_tex';
    readonly dualFboGetBReadFbo: 'dual_fbo_get_b_read_fbo';
    readonly dualFboGetBWriteFbo: 'dual_fbo_get_b_write_fbo';
    readonly dualFboGetBReadTex: 'dual_fbo_get_b_read_tex';
    readonly dualFboGetBWriteTex: 'dual_fbo_get_b_write_tex';
    readonly dualFboIsPresetAAllocated: 'dual_fbo_is_preset_a_allocated';
    readonly dualFboIsPresetBAllocated: 'dual_fbo_is_preset_b_allocated';
    readonly dualFboSetIdleReleaseSeconds: 'dual_fbo_set_idle_release_seconds';
    readonly dualFboGetIdleReleaseSeconds: 'dual_fbo_get_idle_release_seconds';
    readonly dualFboIsPresetBReady: 'dual_fbo_is_preset_b_ready';
    readonly dualFboGetFormat: 'dual_fbo_get_format';
    readonly getContextSnapshot: 'get_context_snapshot';
    readonly getContextLimit: 'get_context_limit';
    readonly dualFboRenderPresetA: 'dual_fbo_render_preset_a';
    readonly dualFboRenderPresetB: 'dual_fbo_render_preset_b';
    readonly transitionStart: 'transition_start';
    readonly transitionCancel: 'transition_cancel';
    readonly transitionIsActive: 'transition_is_active';
    readonly transitionGetBlend: 'transition_get_blend';
    readonly transitionSetDuration: 'transition_set_duration';
    readonly transitionGetDuration: 'transition_get_duration';
    readonly setDeterministicSeed: 'set_deterministic_seed';
    readonly pmSetHostDeterministicSeed: 'pm_set_host_deterministic_seed';
    readonly isDeterministicSeed: 'is_deterministic_seed';
    readonly setDeterministicClock: 'set_deterministic_clock';
    readonly pmSetHostDeterministicClock: 'pm_set_host_deterministic_clock';
    readonly isDeterministicClock: 'is_deterministic_clock';
    readonly deterministicNowMs: 'deterministic_now_ms';
    readonly deterministicFrameIndex: 'deterministic_frame_index';
    readonly setRenderLoopPaused: 'set_render_loop_paused';
    readonly getRhythmBpm: 'get_rhythm_bpm';
    readonly getRhythmBeatPhase: 'get_rhythm_beat_phase';
    readonly getRhythmBarPhase: 'get_rhythm_bar_phase';
    readonly getRhythmConfidence: 'get_rhythm_confidence';
    readonly getRhythmBeatIndex: 'get_rhythm_beat_index';
    readonly getRhythmSection: 'get_rhythm_section';
    readonly setRhythmHint: 'set_rhythm_hint';
