    readonly setHardCutOnBeat: 'set_hard_cut_on_beat';
    readonly setRhythmLatencyMs: 'set_rhythm_latency_ms';
    readonly getRhythmLatencyMs: 'get_rhythm_latency_ms';
    readonly setPresetSwitchPhrase: 'set_preset_switch_phrase';
    readonly setSectionHardCut: 'set_section_hard_cut';
