/** One host's engine calls; see {@link createHostApi}. */
export interface HostApi {
    /** The host handle every method acts on. */
    readonly host: HostHandle;
    /** Tear down projectM engine */
    destruct(): void;
    /** Opaque projectM handle of the active host: the pmHandle the projectm_sprite_*_wrapper and PCM exports take (its host handle, 0 without an engine) */
    getProjectmHandle(): HostHandle;
    /** Initialize (or after a context loss re-initialize) EGL/WebGL and projectM on the host, returns 0 on success, -1 for an unknown host */
    init(): number;
    /** Render-path switches this host's engine runs with as a bitmask (1=blurPath copy, 2=copyPath shader, 4=perPixelEval cpu, 0 without an engine) */
    getRenderPathOverrides(): number;
    /** Tear down and re-init against new canvas selectors (single-instance) */
    rebindCanvases(primary: string, secondary: string): number;
    /** Load preset from Emscripten VFS path */
    loadPresetFile(vfsPath: string): void;
    /** Load preset from VFS path with a hard cut (no crossfade) */
    loadPresetFileHard(vfsPath: string): void;
    /** Advance playlist to next preset */
    switchPreset(): void;
    /** Enable bezel/aspect correction */
    setAspectCorrection(enabled: boolean): void;
    /** Render one visualization frame */
    renderFrame(): void;
    /** Create render targets and start loop */
    startRender(width: number, height: number): void;
    /** Resize projectM viewport */
    setWindowSize(width: number, height: number): void;
    /** Set per-pixel mesh grid size */
    setMesh(width: number, height: number): void;
    /** Register default /presets/ playlist directory */
    addPresetPath(): void;
    /** Bulk-add numbered presets from VFS */
    addExistingVfsPresets(): void;
    /** Add preset file to playlist */
    addPresetFile(vfsPath: string): void;
    /** Add custom_milk_fixed presets by count */
    addCustomMilkPaths(count: number): void;
    /** Feed interleaved float PCM (use feedPcmFloat helper) */
    pcmAddFloat(audioPtr: number, samplesPerChannel: number, channels: number): void;
    /** Allocate the WASM-owned PCM ring (0 = default 16384 frames), returns 1 on success */
    pcmRingInit(capacityFrames: number): number;
    /** Release the PCM ring */
    pcmRingShutdown(): void;
    /** Feed every frame written since the last drain, returns frames fed */
    pcmRingDrain(): number;
    /** Byte offset of the ring's int32 header in the WASM heap */
    getPcmRingHeaderPtr(): number;
    /** Byte offset of the ring's interleaved float storage in the WASM heap */
    getPcmRingDataPtr(): number;
    /** Ring capacity in stereo frames */
    getPcmRingCapacityFrames(): number;
    /** Modulus the ring's frame indices wrap at */
    getPcmRingIndexModulus(): number;
    /** Current producer write index, in frames */
    getPcmRingWriteIndex(): number;
    /** Current drain read index, in frames */
    getPcmRingReadIndex(): number;
    /** Drains that skipped unread audio because producers lapped the ring */
    getPcmRingOverruns(): number;
    /** Create a user sprite on the engine pmHandle names (see create_sprite). Every projectm_sprite_*_wrapper is a no-op for a stale or unknown pmHandle */
    spriteCreate(type: string, code: string): number;
    /** Destroy one user sprite */
    spriteDestroy(spriteId: number): void;
    /** Destroy every user sprite */
    spriteDestroyAll(): void;
    /** Number of live user sprites */
    spriteGetSpriteCount(): number;
    /** Write the live sprite ids, oldest first, to a uint32 array of projectm_sprite_get_sprite_count_wrapper() entries on the WASM heap */
    spriteGetSpriteIds(spriteIds: number): void;
    /** Sprite limit (lowering it destroys the oldest sprites over it) */
    spriteSetMaxSprites(maxSprites: number): void;
    /** Current sprite limit */
    spriteGetMaxSprites(): number;
    /** Value of a sprite expression variable (0 for an unknown sprite or variable) */
    spriteGetVar(spriteId: number, varName: string): number;
    /** Set a sprite expression variable (per-frame code may overwrite it on the next frame) */
    spriteSetVar(spriteId: number, varName: string, value: number): void;
    /** Re-read a texture file rewritten in the VFS into the active host's loaded texture so running presets sample the new image (1 if a loaded texture was updated, 0 if it was not loaded from a file) */
    reloadTexture(name: string): number;
    /** Create or resize a live texture on the active host (RGBA8, starts black, 1..8192 px a side) that presets sample by name (sampler_<name>), with its staging buffer on the WASM heap (1 on success). Register before loading presets that sample it */
    textureSlotRegister(name: string, width: number, height: number): number;
    /** Heap address to write a live texture's next frame to (RGBA8, top row first), or 0 for an unknown slot or when bytes is not its width*height*4 */
    textureSlotBuffer(name: string, bytes: number): number;
    /** Mark the frame written to texture_slot_buffer() complete, for the next render_frame() to upload once (1 if the slot exists) */
    textureSlotCommit(name: string): number;
    /** Generation of a live texture's staging buffer: it changes whenever texture_slot_buffer()'s address would (a resize, or the slot recreated), 0 for an unknown slot. A page that awaited between getting the buffer and writing it checks this first */
    textureSlotGeneration(name: string): number;
    /** texture_slot_commit(), refused for a buffer generation the slot has replaced: 1 committed, 0 unknown slot, -1 stale (the host's last error becomes 3) */
    textureSlotCommitGeneration(name: string, generation: number): number;
    /** Remove a live texture (1 if it existed). Presets sampling it keep its last frame until reloaded */
    textureSlotUnregister(name: string): number;
    /** Set a per-frame variable (q1..q32, zoom, decay, wave_r, ...) for every preset from the next frame on, loaded before the preset's per-frame code runs, until eval_clear() (1 if accepted, read-only inputs such as time or bass are refused) */
    evalSet(name: string, value: number): number;
    /** Remove an eval_set() value, or every value for an empty name (1 if one was removed) */
    evalClear(name: string): number;
    /** Lock or unlock automatic preset switching */
    setPresetLocked(locked: boolean): void;
    /** Enable glass-layer transparency on near-black pixels */
    setTransparencyMode(enabled: boolean): void;
    /** Whether transparency mode is enabled */
    getTransparencyMode(): boolean;
    /** Set RGB threshold for transparency mode (default 0.01) */
    setTransparencyThreshold(threshold: number): void;
    /** Current transparency threshold */
    getTransparencyThreshold(): number;
    /** Toggle on-canvas performance HUD */
    setPerfHud(enabled: number): void;
    /** Set render target frame rate */
    setTargetFps(fps: number): void;
    /** Enable adaptive quality governor */
    setQualityGovernor(enabled: boolean): void;
    /** Current quality tier index (0=high, 1=regular, 2=low) */
    getQualityTier(): number;
    /** Best quality tier the governor may step up to (0 = no cap, 1 = regular, 2 = low), applied at once to a running governor above it (the battery context profile sets 1) */
    setQualityTierCeiling(tier: number): void;
    /** Best quality tier the governor may choose (set_quality_tier_ceiling) */
    getQualityTierCeiling(): number;
    /** Current governor internal render-scale factor (1.0/0.75/0.5) */
    getGovernorRenderScale(): number;
    /** Current governor blur-level cap (-1 = unlimited, else 0-3) */
    getGovernorBlurCap(): number;
    /** Whether preset shaders are ready */
    isPresetReady(minFramesSinceReady: number): number;
    /** Total frames rendered since init */
    getRenderedFrameCount(): number;
    /** Whether last preset switch failed (0/1) */
    presetSwitchFailed(): number;
    /** Begin preset load with optional transpiled GLSL cache key */
    shaderCacheBeginLoad(cacheKey: string): void;
    /** Inject cached transpiled GLSL (0=warp, 1=composite) */
    shaderCacheImportGlsl(shaderType: number, glsl: string): void;
    /** Clear transpiled GLSL cache key after preset load */
    shaderCacheEndLoad(): void;
    /** Allocate preset-B FBO for transition */
    dualFboBeginTransition(): boolean;
    /** Finalize dual-FBO transition */
    dualFboEndTransition(): void;
    /** Cancel in-progress dual-FBO transition */
    dualFboCancelTransition(): void;
    /** Swap preset A ping-pong buffers */
    dualFboSwapPresetA(): void;
    /** Swap preset B ping-pong buffers */
    dualFboSwapPresetB(): void;
    /** Preset A read FBO handle */
    dualFboGetAReadFbo(): number;
    /** Preset A write FBO handle */
    dualFboGetAWriteFbo(): number;
    /** Preset A read texture handle */
    dualFboGetAReadTex(): number;
    /** Preset A write texture handle */
    dualFboGetAWriteTex(): number;
    /** Preset B read FBO handle */
    dualFboGetBReadFbo(): number;
    /** Preset B write FBO handle */
    dualFboGetBWriteFbo(): number;
    /** Preset B read texture handle */
    dualFboGetBReadTex(): number;
    /** Preset B write texture handle */
    dualFboGetBWriteTex(): number;
    /** Whether preset-A FBO is allocated (lazily allocated per transition) */
    dualFboIsPresetAAllocated(): boolean;
    /** Whether preset-B FBO is allocated */
    dualFboIsPresetBAllocated(): boolean;
    /** Idle seconds before the preset-A FBO pair is reclaimed (0=immediate, <0=never) */
    dualFboSetIdleReleaseSeconds(seconds: number): void;
    /** Configured preset-A idle release threshold in seconds */
    dualFboGetIdleReleaseSeconds(): number;
    /** Whether preset-B shaders are ready */
    dualFboIsPresetBReady(): boolean;
    /** Dual-FBO format (0=RGBA16F, 1=RGBA32F, 2=RGBA8 — the fboPrecision numbering) */
    dualFboGetFormat(): number;
    /** What this host negotiated with WebGL, packed in an int (0 before init): bit0 has a context, bit1 EXT_color_buffer_float, bit2 EXT_float_blend, bit3 WEBGL_lose_context present, bits 8-9 active dual-FBO format (0=RGBA16F, 1=RGBA32F, 2=RGBA8), bit14 EXT_disjoint_timer_query_webgl2 offered, bit15 get_context_limit() answers. Decoded into ProjectMContext.contextSnapshot and contextCaps */
    getContextSnapshot(): number;
    /** One limit of this host's WebGL context, read when it was created (which: 0 MAX_TEXTURE_SIZE, 1 MAX_RENDERBUFFER_SIZE, 2 MAX_SAMPLES), 0 without a context. Decoded into ProjectMContext.contextCaps */
    getContextLimit(which: number): number;
    /** Render preset A into dual FBO */
    dualFboRenderPresetA(): void;
    /** Render preset B into dual FBO */
    dualFboRenderPresetB(): void;
    /** Start visual preset transition blend */
    transitionStart(): void;
    /** Cancel active transition */
    transitionCancel(): void;
    /** Whether a transition is in progress */
    transitionIsActive(): boolean;
    /** Current transition blend factor 0..1 */
    transitionGetBlend(): number;
    /** Set transition duration in seconds */
    transitionSetDuration(seconds: number): void;
    /** Configured transition duration in seconds */
    transitionGetDuration(): number;
    /** Pin this host's engine's RNG to a seed so a preset renders identical pixels run to run. It covers what the engine draws from then on: for what it draws while it is created, set_deterministic_seed() before create_host */
    setHostDeterministicSeed(enabled: boolean, seed: number): void;
    /** Whether this host's engine has a deterministic seed */
    isDeterministicSeed(): boolean;
    /** Drive this host's engine from a virtual clock where frame N happens at N/fps (golden-image capture only, never perf runs) */
    setHostDeterministicClock(enabled: boolean, fps: number): void;
    /** Whether this host's virtual clock is active */
    isDeterministicClock(): boolean;
    /** The host time base in milliseconds: virtual when the clock is on, real otherwise */
    deterministicNowMs(): number;
    /** Frames ticked since the virtual clock was last enabled */
    deterministicFrameIndex(): number;
    /** Tempo in BPM from the rhythm analysis (0 while the tracker is not confident) */
    getRhythmBpm(): number;
    /** Beat phase 0..1, 0 = the (predicted) beat */
    getRhythmBeatPhase(): number;
    /** Bar phase 0..1 over four beats, 0 = downbeat */
    getRhythmBarPhase(): number;
    /** Tempo tracker confidence 0..1 (1 while a tempo hint is set) */
    getRhythmConfidence(): number;
    /** Beats counted since the engine started */
    getRhythmBeatIndex(): number;
    /** Section index, incremented on every detected section change */
    getRhythmSection(): number;
    /** Use a known tempo (MIDI clock, track BPM) instead of estimating it (0 goes back to estimating) */
    setRhythmHint(bpm: number): void;
    /** Switch presets on the timer (0), every N bars (1) or on a detected section change (2), bars 0 = 16 */
    setPresetSwitchPolicy(policy: number, bars: number): void;
    /** Preset switch policy (0 timer, 1 bars, 2 section) */
    getPresetSwitchPolicy(): number;
    /** Crossfade length in beats, resolved against the tempo when each crossfade starts (0 = use seconds) */
    transitionSetDurationBeats(beats: number): void;
    /** Configured crossfade length in beats (0 = seconds) */
    transitionGetDurationBeats(): number;
    /** Make beat-detection hard cuts wait for the next beat */
    setHardCutOnBeat(enabled: boolean): void;
    /** Delay the beat clock (and switches on it) by the audio output latency, 0..1000 ms, so the visual beat matches the audible one */
    setRhythmLatencyMs(ms: number): void;
    /** Output latency compensated by the beat clock, ms */
    getRhythmLatencyMs(): number;
    /** Quantise bar/section switches to phrases of N bars counted from the last section change (0 = off) */
    setPresetSwitchPhrase(bars: number): void;
    /** Hard cut on the first downbeat after each detected section change (a drop cut) */
    setSectionHardCut(enabled: boolean): void;
    /** Report beats, bars and section changes to globalThis.pmOnRhythmEvent (off by default) */
    setRhythmEvents(enabled: boolean): void;
    /** Turn the temporal flash limiter on or off (off by default, see docs/FLASH_LIMITER.md) */
    setFlashLimitEnabled(enabled: boolean): void;
    /** Whether the flash limiter is on */
    getFlashLimitEnabled(): boolean;
    /** Span of mean relative luminance (0.005..1, default 0.06) the presented frames may cover within the limiter's ~1/3 s memory */
    setFlashLimitThreshold(threshold: number): void;
    /** The flash limiter's threshold */
    getFlashLimitThreshold(): number;
    /** Frames the flash limiter blended toward the previous frame since it was enabled (reads back from the GPU: poll a few times a second at most) */
    getFlashLimitClampedFrames(): number;
    /** emscripten_webgl_commit_frame() calls since the host was created (0 unless the host presents manually) */
    getCommittedFrameCount(): number;
    /** Read back the next rendered frame (1 accepted, 0 no context), replacing an unclaimed capture */
    captureFrameRequest(): number;
    /** Capture state: 0 idle, 1 requested, 2 pending (GPU read in flight), 3 ready, 4 failed (never waits) */
    captureFrameStatus(): number;
    /** capture_frame_status(), but wait=true takes a pending capture now, waiting for the GPU if it must */
    captureFrameResolve(wait: boolean): number;
    /** Heap address of the ready capture's RGBA8 pixels, top row first (0 unless ready) */
    captureFrameDataPtr(): number;
    /** Width in pixels of the last capture */
    captureFrameWidth(): number;
    /** Height in pixels of the last capture */
    captureFrameHeight(): number;
    /** get_rendered_frame_count() right after the captured frame */
    captureFrameIndex(): number;
    /** Free the captured pixels */
    captureFrameRelease(): void;
    /** Test hook for the page-event queue: raises every page event about this host from inside the export, returning how many were raised with the host intact after each (-1 if one destroyed it underneath) */
    debugEmitEvents(): number;
    /** Test hook for the exception barrier: 1 throws std::runtime_error, 2 allocates past the heap (std::bad_alloc), returning 1 if nothing was thrown */
    debugThrow(kind: number): number;
    /** Code of this host's last init() failure, 0 after a success (docs/EMSCRIPTEN.md Init Error Codes) */
    getInitError(): number;
    /** Code of the last error an export reported on this host (0 none, 1 exception, 2 out of memory, 3 stale buffer generation), see pm_get_last_error_message */
    getLastError(): ProjectMError;
    /** Message of the last error an export reported on this host ("" for none) */
    getLastErrorMessage(): string;
    /** Reset this host's last error to 0 */
    clearLastError(): void;
    /** Tear down this host's engine and GL state after its WebGL context was lost (the per-host form of pm_handle_context_loss) */
    contextLost(): void;
}

